     1	package hotel.reservations;
     2	
     3	import hotel.rooms.Room;
     4	import java.math.BigDecimal;
     5	import java.math.RoundingMode;
     6	import java.time.LocalDate;
     7	import java.time.Month;
     8	
     9	/**
    10	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
    11	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
    12	 * (half-even) at every step.
    13	 */
    14	public final class PriceCalculator {
    15	
    16	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
    17	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    18	
    19	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
    20	        int nights = 0;
    21	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    22	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    23	            subtotal = subtotal.add(nightPrice(room, night));
    24	            nights++;
    25	        }
    26	        BigDecimal discount = switch (ratePlan) {
    27	            case STANDARD -> cents(BigDecimal.ZERO);
    28	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
    29	        };
    30	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
    31	    }
    32	
    33	    BigDecimal nightPrice(Room room, LocalDate night) {
    34	        BigDecimal nightlyRate = room.nightlyRate();
    35	        if (isHighSeason(night)) {
    36	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
    37	        }
    38	        return cents(nightlyRate);
    39	    }
    40	
    41	    /** High season: from December 15 to the end of February, and the whole of July. */
    42	    static boolean isHighSeason(LocalDate date) {
    43	        Month month = date.getMonth();
    44	        return month == Month.JANUARY
    45	                || month == Month.FEBRUARY
    46	                || month == Month.JULY
    47	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
    48	    }
    49	
    50	    static BigDecimal cents(BigDecimal value) {
    51	        return value.setScale(2, RoundingMode.HALF_EVEN);
    52	    }
    53	}
