323	     8	
324	     9	/**
325	    10	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
326	    11	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
327	    12	 * (half-even) at every step.
328	    13	 */
329	    14	public final class PriceCalculator {
330	    15	
331	    16	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
332	    17	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
333	    18	
334	    19	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
335	    20	        int nights = 0;
336	    21	        BigDecimal subtotal = cents(BigDecimal.ZERO);
337	    22	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
338	    23	            subtotal = subtotal.add(nightPrice(room, night));
339	    24	            nights++;
340	    25	        }
341	    26	        BigDecimal discount = switch (ratePlan) {
342	    27	            case STANDARD -> cents(BigDecimal.ZERO);
343	    28	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
344	    29	        };
345	    30	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
346	    31	    }
347	    32	
348	    33	    BigDecimal nightPrice(Room room, LocalDate night) {
349	    34	        BigDecimal nightlyRate = room.nightlyRate();
350	    35	        if (isHighSeason(night)) {
351	    36	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
352	    37	        }
353	    38	        return cents(nightlyRate);
354	    39	    }
355	    40	
356	    41	    /** High season: from December 15 to the end of February, and the whole of July. */
357	    42	    static boolean isHighSeason(LocalDate date) {
358	    43	        Month month = date.getMonth();
359	    44	        return month == Month.JANUARY
360	    45	                || month == Month.FEBRUARY
361	    46	                || month == Month.JULY
362	    47	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
363	    48	    }
364	    49	
365	    50	    static BigDecimal cents(BigDecimal value) {
366	    51	        return value.setScale(2, RoundingMode.HALF_EVEN);
367	    52	    }
368	    53	}
